<script lang="ts">import { enhance } from '$app/forms'; import type { ActionData, PageServerData } from './$types'; let { data, form }: { data: PageServerData; form: ActionData } = $props();</script><svelte:head><title>Account settings · LinkGarden</title><meta name="robots" content="noindex" /></svelte:head><p><a href="/settings/profile">← Profile settings</a></p><h1>Account settings</h1><section class="card danger-zone"><h2>Delete account</h2>{#if data.blockers.length}<p>Deletion is blocked until you transfer or delete these public or shared lists:</p><ul>{#each data.blockers as item}<li><a href={'/app/lists/' + item.id}>{item.title}</a> ({item.visibility})</li>{/each}</ul>{:else}<p>Your private unshared lists and personal links will be deleted. Links you added to other people’s lists remain without your attribution.</p><form method="post" action="?/deleteAccount" use:enhance><label>Confirm your password <input required type="password" name="password" autocomplete="current-password" /></label>{#if form?.message}<p class="error">{form.message}</p>{/if}<button class="danger">Permanently delete account</button></form>{/if}</section>
